      "hành động": [
        "phanh gấp",
        "dừng đột ngột"
      ]
    },
    "K03": {
      "tên": "Tiến sát xe phía trước chạy chậm",
      "hành động": [
        "không giảm tốc",
        "tăng tốc"
      ]
    },
    "K04": {
      "tên": "Chuyển làn, nhập làn",
      "hành động": [
        "chuyển sang làn bên trái",
        "chuyển sang làn bên phải"
      ]
    },
    "K05": {
      "tên": "Vượt, len giữa các xe",
      "hành động": [
        "vượt bên trái",
        "vượt bên phải",
        "len giữa"
      ]
    },
    "K06": {
      "tên": "Rẽ cắt qua xe đi cùng chiều bên cạnh",
      "hành động": [
        "rẽ trái",
        "rẽ phải"
      ]
    },
    "K07": {
      "tên": "Xe đỗ ven đường, mở cửa, ra khỏi chỗ đỗ",
      "hành động": [
        "mở cửa xe",
        "ra khỏi chỗ đỗ"
      ]
    },
    "K08": {
      "tên": "Lấn sang phần đường ngược chiều",
      "hành động": [
        "lấn khi vượt",
        "lấn khi vào cua",
        "lấn khi đi thẳng"
      ]
    },
    "K09": {
      "tên": "Đi ngược chiều trên làn của người khác",
      "hành động": [
        "đi thẳng ngược chiều"
      ]
    },
    "K10": {
      "tên": "Rẽ trái hoặc quay đầu cắt đầu xe ngược chiều",
      "hành động": [
        "rẽ trái",
        "quay đầu"
      ]
    },
    "K11": {
      "tên": "Hai hướng cắt nhau tại giao lộ, cùng đi thẳng",
      "hành động": [
        "từ trái sang phải",
        "từ phải sang trái"
      ]
    },
    "K12": {
      "tên": "Ra từ đường nhánh, hẻm, bãi xe",
      "hành động": [
        "ra từ bên trái",
        "ra từ bên phải"
      ]
    },
    "K13": {
      "tên": "Quay đầu giữa đường",
      "hành động": [
        "quay đầu sang trái",
        "quay đầu sang phải"
      ]
    },
    "K14": {
      "tên": "Băng ngang đường giữa đoạn",
      "hành động": [
        "từ trái sang phải",
        "từ phải sang trái"
      ]
    },
    "K15": {
      "tên": "Người đi bộ băng qua hoặc đi dưới lòng đường",
      "hành động": [
        "từ trái sang phải",
        "từ phải sang trái",
        "đi dọc đường"
      ]
    },
    "K16": {
      "tên": "Động vật lao ra đường",
      "hành động": [
        "từ trái sang phải",
        "từ phải sang trái"
      ]
    },
    "K17": {
      "tên": "Lùi xe vào bên khác",
      "hành động": [
        "lùi xe"
      ]
    },
    "K18": {
      "tên": "Một bên trượt, văng, không do bên kia",
      "hành động": [
        "trượt",
        "văng khỏi làn",
        "nổ lốp"
      ]
    }
  },
  "tốc độ": [
    "phanh gấp",
    "dừng đột ngột",
    "tăng tốc",
    "không giảm tốc",
    "đứng yên"
  ],
  "bên né": [
    "chủ thể",
    "đối tượng",
    "cả hai"
  ],
  "cách né": [
    "phanh gấp",
    "đánh lái sang trái",
    "đánh lái sang phải",
    "phanh gấp và đánh lái"
  ],
  "kết quả né": [
    "tránh được",
    "ngã, trượt",
    "vẫn chạm",
    "chạm vào thực thể khác"
  ]
}

Schema output cho mỗi câu:
{
  "ô": {
    "<tên ô>": {
      "trạng thái": "M | T | K",
      "giá trị": "<nhãn nguyên văn trong codebook, hoặc mô tả thực thể> | null",
      "bằng chứng": "<đoạn nguyên văn> | null",
      "cụm không khớp": "<chỉ khi K> | null"
    }
  },
  "ngoài codebook": [{"đoạn": "<nguyên văn>", "loại": "<loại>"}],
  "ghi chú": "<chỉ khi câu mơ hồ> | null"
}

Bạn sẽ nhận nhiều câu trả lời trong một lần, mỗi câu có số thứ tự [1], [2], ... Map từng câu độc lập với các câu khác. Trả về đúng một JSON dạng {"kết quả": [ ... ]}, mỗi phần tử là output theo schema ở trên cho một câu và có thêm khóa "id" là số thứ tự của câu đó (dạng chuỗi). Đủ mọi id, giữ đúng thứ tự.

